package com.wedo.backend.poll.entity;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="poll_options") public class PollOptionEntity { @Id private UUID id; @Column(name="poll_id",nullable=false) private UUID pollId; @Column(nullable=false) private String text; @Column(name="sort_order",nullable=false) private int sortOrder; @Column(name="is_disabled",nullable=false) private boolean disabled; @Column(name="created_by") private UUID createdBy; @Column(name="created_at",nullable=false) private Instant createdAt; protected PollOptionEntity(){} public PollOptionEntity(UUID id,UUID pollId,String text,int sortOrder,UUID createdBy,Instant now){this.id=id;this.pollId=pollId;this.text=text;this.sortOrder=sortOrder;this.createdBy=createdBy;this.createdAt=now;} public UUID getId(){return id;} public UUID getPollId(){return pollId;} public String getText(){return text;} public int getSortOrder(){return sortOrder;} public boolean isDisabled(){return disabled;} public UUID getCreatedBy(){return createdBy;} public void update(String text){this.text=text;} public void disable(){this.disabled=true;} }
